    for key in ['source_words_10bin','candidate_words_10bin','word_ratio_005bin','character_ratio_005bin','punctuation_counts','source_dataset','id_mod4','id_mod5','id_mod20','row_mod4','row_mod5']:
        lines.append(f"| {key} | {a['train'][key]['oracle_bucket_purity']:.4f} | {a['dev'][key]['oracle_bucket_purity']:.4f} |")
